describe("services/billing-service", () => {
  // checkLimit reads the ceiling from getPlanLimits(), never a hard-coded number.
  it("computes remaining and exceeded from the plan's quota", async () => {
    const tenant = await createTenant("billing-remaining", "starter");
    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 4 });

    const check = await billingService.checkLimit(tenant.org.id, "seats", 1);

    expect(check.plan).toBe("starter");
    expect(check.limit).toBe(10);
    expect(check.used).toBe(4);
    expect(check.remaining).toBe(6);
    expect(check.exceeded).toBe(false);
  });

  // At exactly the quota the resource is exceeded and remaining is zero.
  it("marks a resource exceeded at, not past, the quota", async () => {
    const tenant = await createTenant("billing-exact", "starter");
    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 10 });

    const check = await billingService.checkLimit(tenant.org.id, "seats");

    expect(check.limit).toBe(10);
    expect(check.used).toBe(10);
    expect(check.remaining).toBe(0);
    expect(check.exceeded).toBe(true);
  });

  // An unlimited enterprise quota is never exceeded and reports Infinity remaining.
  it("never marks an unlimited quota exceeded", async () => {
    const tenant = await createTenant("billing-unlimited", "enterprise");
    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 1_000_000 });

    const check = await billingService.checkLimit(tenant.org.id, "seats", 500);

    expect(check.limit).toBe(Number.POSITIVE_INFINITY);
    expect(check.exceeded).toBe(false);
    expect(check.remaining).toBe(Number.POSITIVE_INFINITY);
  });

  // A downgrade whose current usage breaches the target plan is refused.
  it("refuses a downgrade that current usage would breach", async () => {
    const tenant = await createTenant("billing-downgrade", "growth");
    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 5 });

    await expect(
      billingService.changePlan(tenant.actors.owner, {
        orgId: tenant.org.id,
        plan: "free",
        interval: "monthly",
      }),
    ).rejects.toThrow(/seats exceeds its limit/);
  });

  // billing.plan_changed carries the previous and new plan.
  it("emits billing.plan_changed on a successful plan change", async () => {
    const tenant = await createTenant("billing-plan-changed", "growth");

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("billing.plan_changed", (payload) => {
        resolve(payload);
      });
      void billingService.changePlan(tenant.actors.owner, {
        orgId: tenant.org.id,
        plan: "enterprise",
        interval: "monthly",
      });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      from: "growth",
      to: "enterprise",
    });
  });

  // Crossing a ceiling emits billing.limit_exceeded with resource, limit and used.
  it("emits billing.limit_exceeded when a ceiling is crossed", async () => {
    const tenant = await createTenant("billing-limit-exceeded", "starter");
    await usageRepo.incrementUsage(tenant.org.id, { projectsUsed: 10 });

    let off: Unsubscribe | undefined;
    const receivedPromise = new Promise((resolve) => {
      off = subscribe("billing.limit_exceeded", (payload) => {
        resolve(payload);
      });
    });

    await expect(
      billingService.assertWithinLimit(tenant.org.id, "projects", 1),
    ).rejects.toThrow(/allows 10 projects/);

    const received = await receivedPromise;
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      resource: "projects",
      limit: 10,
      used: 10,
    });
  });

  // can(actor, "org:manage_billing", …) — only an owner may change the plan.
  it("refuses a plan change to anyone but an owner", async () => {
    const tenant = await createTenant("billing-owner-only", "growth");

    await expect(
      billingService.changePlan(tenant.actors.admin, {
        orgId: tenant.org.id,
        plan: "enterprise",
        interval: "monthly",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
});
import { mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import * as schema from "./schema";

/**
 * The single Drizzle connection for the process.
 *
 * Repositories import `db` from `@/server/db` (the barrel), never this module
 * directly, so the connection can be swapped in tests. Never construct a
 * second `Database` — SQLite in WAL mode tolerates it, but the in-process
 * event bus assumes one writer.
 */

const DEFAULT_DB_PATH = "./data/taskflow.db";

let instance: ReturnType<typeof createClient> | null = null;

function createClient(path: string) {
  const absolute = resolve(process.cwd(), path);
  mkdirSync(dirname(absolute), { recursive: true });
  const sqlite = new Database(absolute);
  sqlite.pragma("journal_mode = WAL");
  sqlite.pragma("foreign_keys = ON");
  return drizzle(sqlite, { schema });
}

export function getDb(path: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH) {
  instance ??= createClient(path);
  return instance;
}

/** Test hook: point the singleton at an in-memory database. */
export function useInMemoryDb(): void {
  instance = createClient(":memory:");
}

export type Db = ReturnType<typeof getDb>;
export type DbSchema = typeof schema;
/**
 * Cache tag vocabulary and revalidation helpers.
 *
 * Next 16 requires a cache-life profile as the second argument to
 * `revalidateTag`, which is exactly the kind of API change that rots when it
 * is spelled out at forty call sites. Server Actions call
 * `revalidateTagged([...])` and never import `next/cache` themselves.
 */
import { revalidateTag } from "next/cache";
import type { IssueId, OrgId, ProjectId } from "@/types/common";

/** The cache-life profiles this app uses, by how stale a read may be. */
export const CACHE_PROFILES: Readonly<
  Record<"seconds" | "minutes" | "hours", string>
> = {
  seconds: "seconds",
  minutes: "minutes",
  hours: "hours",
};

export function orgTag(orgId: OrgId): string {
  return `org:${orgId}`;
}

export function projectTag(projectId: ProjectId): string {
  return `project:${projectId}`;
}

export function issueTag(issueId: IssueId): string {
  return `issue:${issueId}`;
}

/**
 * Invalidates every supplied tag under one profile, de-duplicating first so a
 * caller can splice together tag lists without worrying about repeats.
 */
export function revalidateTagged(
  tags: readonly string[],
  profile: string = CACHE_PROFILES.minutes,
): void {
  for (const tag of new Set(tags)) {
    if (tag === "") continue;
    revalidateTag(tag, profile);
  }
}
"use server";

/**
 * Changes plan; refuses a downgrade that would breach a current quota.
 *
 * Owner D. The interesting case is the *downgrade*: the target plan's limits
 * are compared against today's usage before the switch, so an org on growth
 * with 40 seats cannot silently drop to starter and strand 37 people.
 *
 * Must call (do not reimplement): changePlanSchema, can, getPlanLimits,
 * wouldExceedLimit, getActor, toActionResult
 */

import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { changePlanSchema, type ChangePlanInput } from "@/schemas/billing";
import { changePlan } from "@/server/services/billing-service";
import { getUsage } from "@/server/services/usage-service";
import type { ActionResult } from "@/types/api";
import type { LimitedResource, Subscription } from "@/types/billing";
import type { Actor } from "@/types/member";

const run = withAction<typeof changePlanSchema, Subscription>(
  changePlanSchema,
  async (raw, actor) => {
    const input = raw as ChangePlanInput;

    if (!can(actor, "org:manage_billing", { kind: "billing", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:manage_billing");
    }

    await assertPlanFitsCurrentUsage(actor, input);

    const subscription = await changePlan(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.hours);
    return subscription;
  },
  { revalidate: ["billing"], cacheProfile: "hours" },
);

/**
 * Compares live usage against the *target* plan. `wouldExceedLimit` is called
 * with a requested delta of zero: we are not consuming anything, only asking
 * whether what is already in use still fits.
 */
async function assertPlanFitsCurrentUsage(
  actor: Actor,
  input: ChangePlanInput,
): Promise<void> {
  const usage = await getUsage(actor, input.orgId);
  const limits = getPlanLimits(input.plan);

  const consumption: ReadonlyArray<readonly [LimitedResource, number]> = [
    ["seats", usage.seatsUsed],
    ["projects", usage.projectsUsed],
    ["storageMb", usage.storageMbUsed],
  ];

  for (const [resource, used] of consumption) {
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new PlanLimitError(resource, limits[resource], used);
    }
  }
}

export async function changePlanAction(raw: unknown): Promise<ActionResult<Subscription>> {
  return run(raw);
}
